import { Image } from 'expo-image';
import { StyleSheet, View } from 'react-native';

import { brand } from '@/theme/brand';

import { VyroMark } from './VyroMark';

// Intrinsic sizes of the @1x rasters generated by scripts/brand/generate-assets.mjs.
const WORDMARK_RATIO = 45 / 240;
const TAGLINE_RATIO = 16 / 240;

const wordmarkBase = require('@/assets/brand/wordmark-base.png');
const wordmarkAccent = require('@/assets/brand/wordmark-accent.png');
const taglineMask = require('@/assets/brand/tagline-mask.png');

export type VyroLogoVariant = 'stacked' | 'horizontal' | 'markOnly';

export type VyroLogoProps = {
  variant?: VyroLogoVariant;
  /** Width of the whole lockup in dp. */
  width?: number;
  color?: string;
  /** Show "TRAIN • TRACK • EVOLVE" (stacked variant only). */
  tagline?: boolean;
  glow?: boolean;
  testID?: string;
};

/**
 * The wordmark is two stacked rasters: white letters, plus a white mask of the lime parts
 * tinted with the accent. This keeps the supplied lettering exact while following the theme.
 * "VYRO" is never rendered in a text font (roadmap step 02).
 */
function Wordmark({ width, color }: { width: number; color: string }) {
  const style = { width, height: width * WORDMARK_RATIO };
  return (
    <View style={style}>
      <Image source={wordmarkBase} style={StyleSheet.absoluteFill} contentFit="contain" />
      <Image
        source={wordmarkAccent}
        style={StyleSheet.absoluteFill}
        contentFit="contain"
        tintColor={color}
      />
    </View>
  );
}

export function VyroLogo({
  variant = 'stacked',
  width = 240,
  color = brand.primary,
  tagline = true,
  glow = true,
  testID,
}: VyroLogoProps) {
  const a11y = {
    accessible: true,
    accessibilityRole: 'image' as const,
    accessibilityLabel: tagline && variant === 'stacked' ? 'VYRO. Train, track, evolve.' : 'VYRO',
    ...(testID ? { testID } : {}),
  };

  if (variant === 'markOnly') {
    return (
      <View {...a11y}>
        <VyroMark size={width} color={color} glow={glow} accessibilityLabel="VYRO" />
      </View>
    );
  }

  if (variant === 'horizontal') {
    const markSize = width * 0.22;
    return (
      <View {...a11y} style={styles.row}>
        <VyroMark size={markSize} color={color} glow={false} />
        <Wordmark width={width - markSize - 12} color={color} />
      </View>
    );
  }

  return (
    <View {...a11y} style={styles.stack}>
      <VyroMark size={width * 0.6} color={color} glow={glow} />
      <Wordmark width={width} color={color} />
      {tagline ? (
        <Image
          source={taglineMask}
          style={{ width, height: width * TAGLINE_RATIO, marginTop: width * 0.05 }}
          contentFit="contain"
          tintColor={color}
        />
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'center', gap: 12 },
  stack: { alignItems: 'center', gap: 10 },
});
